const body = $json.body || {};
const clean = (value, limit = 1500) => String(value ?? '').trim().slice(0, limit);

if (clean(body.website)) throw new Error('Submission rejected.');
const startedAt = Number(body.startedAt || 0);
if (!startedAt || Date.now() - startedAt < 1500) throw new Error('Submission was too fast.');

const data = {
  fullName: clean(body.fullName, 120),
  phone: clean(body.phone, 30),
  email: clean(body.email, 160).toLowerCase(),
  bestContactTime: clean(body.bestContactTime, 40),
  applyingFor: clean(body.applyingFor, 40),
  occupants: clean(body.occupants, 3),
  moveIn: clean(body.moveIn, 60),
  currentHousing: clean(body.currentHousing, 1000),
  housingOnly: clean(body.housingOnly, 80),
  paymentSource: clean(body.paymentSource, 80),
  additional: clean(body.additional, 1500),
  consent: clean(body.consent, 10)
};

const required = ['fullName','phone','bestContactTime','applyingFor','occupants','moveIn','currentHousing','housingOnly','paymentSource','consent'];
if (required.some((field) => !data[field])) throw new Error('Please complete all required fields.');
if (!/^\d{1,2}$/.test(data.occupants) || Number(data.occupants) < 1 || Number(data.occupants) > 20) throw new Error('Please enter a valid number of occupants.');
if (data.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email)) throw new Error('Please enter a valid email address.');

const date = new Date().toISOString().slice(0, 10).replaceAll('-', '');
const suffix = Math.floor(1000 + Math.random() * 9000);
return [{ json: { ...data, reference: `TCL-${date}-${suffix}`, receivedAt: new Date().toISOString() } }];

